def f(n):
    a = n // 10
    b = n % 10
    return a + 3 * b

def find_cycles(max_n):
    cycles = []
    visited = {}
    for i in range(max_n + 1):
        path = []
        curr = i
        while curr not in path and curr not in visited:
            path.append(curr)
            curr = f(curr)
        if curr in path:
            cycle = path[path.index(curr):]
            cycles.append(cycle)
        for p in path:
            visited[p] = True
    return cycles

cycles = find_cycles(1000)
print(cycles)

